// Builder: build on a plot, block by block. Your build is saved, so it's still here next time.
// Mouse: left-click places the selected block on the face you point at, right-click digs.
// The wheel, O, or a click on the hotbar picks a block. X switches between building and digging
// (handy on a touch screen, where a tap is a left click). Hold X to clear the plot.
// Arrows turn and raise the camera.
// Shows: mray() and the face it hit (place a block at the cell + the face direction), mset(),
// a hotbar drawn with rectfill/print and clicked through mouse_pos(), save()/load() for a build.
// map 0 = the plot, 16 x 8 x 16. Tiles 1-9 are building blocks; 10 is the ground (can't be dug).
// sounds: 0 place, 1 dig, 2 can't, 3 switch mode, 4 pick a block

const W = 16, H = 8, D = 16
const BLOCKS = [1, 2, 3, 4, 5, 6, 7, 8, 9]        // the hotbar: tile numbers
const ICON = [0, 11, 4, 6, 8, 15, 20, 3, 10, 12]  // a color for each tile's hotbar square
let sel = 0, digging = false, wheel = 0
let ang = 0.12, lift = 0.11, target = null
let dirty = false, saveT = 0, clearT = 0

function _init() {
  mouse_set_mode(1)                               // click mode; on touch screens a tap is a click
  bg(12)
  let d = load()
  if (d && d.blocks && d.blocks.length == W * H * D) {
    // one character per cell, in the same order as the map's data: x fastest, then y, then z
    for (let i = 0; i < d.blocks.length; i++)
      mset(0, i % W, flr(i / W) % H, flr(i / (W * H)), parseInt(d.blocks[i], 36))
  }
}

function saveBuild() {
  let s = ''
  for (let z = 0; z < D; z++) for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) s += mget(0, x, y, z).toString(36)
  save({ blocks: s })
}

function pick(i) { sel = (i + BLOCKS.length) % BLOCKS.length; sfx(4) }

function _update() {
  if (btn(0)) ang -= 0.005
  if (btn(1)) ang += 0.005
  if (btn(2)) lift = min(lift + 0.003, 0.22)
  if (btn(3)) lift = max(lift - 0.003, 0.02)
  if (btnp(4)) pick(sel + 1)
  wheel += mouse_wheel()                          // trackpads scroll in fractions of a notch
  while (wheel >= 1) { wheel--; pick(sel + 1) }
  while (wheel <= -1) { wheel++; pick(sel - 1) }

  // X: tap to switch build / dig, hold to clear the plot
  if (btn(5)) {
    if (++clearT == 90) {
      for (let z = 0; z < D; z++) for (let y = 1; y < H; y++) for (let x = 0; x < W; x++) mset(0, x, y, z, 0)
      dirty = true; sfx(1)
    }
  } else {
    if (clearT > 0 && clearT < 90) { digging = !digging; sfx(3) }
    clearT = 0
  }

  let [mx, my] = mouse_pos()
  if (my >= 229 && mx >= 32 && mx < 32 + BLOCKS.length * 22) {     // over the hotbar
    target = null
    if (btnp(19)) pick(flr((mx - 32) / 22))
  } else {
    let h = mray(0, ...mouse_ray())
    target = h[0] ? h : null
    if (target && (btnp(19) || btnp(20))) {
      let [t, x, y, z, nx, ny, nz] = target
      if (btnp(20) || digging) {                  // right-click always digs
        if (t != 10) { mset(0, x, y, z, 0); sfx(1); dirty = true } else sfx(2)
      } else {
        let [px, py, pz] = [x + nx, y + ny, z + nz]
        if (px >= 0 && py >= 0 && pz >= 0 && px < W && py < H && pz < D && !mget(0, px, py, pz)) {
          mset(0, px, py, pz, BLOCKS[sel]); sfx(0); dirty = true
        } else sfx(2)
      }
    }
  }
  if (dirty && ++saveT >= 30) { saveBuild(); dirty = false; saveT = 0 }   // at most twice a second
}

// a wire box around block (x, y, z), a little outside it
function box(x, y, z, c) {
  let e = 0.03, p = (k) => [x - e + (k & 1) * (1 + 2 * e), y - e + (k >> 1 & 1) * (1 + 2 * e), z - e + (k >> 2 & 1) * (1 + 2 * e)]
  for (let i = 0; i < 8; i++) for (let bit of [1, 2, 4]) if (!(i & bit)) line3(...p(i), ...p(i | bit), c)
}

function _draw() {
  let cx = W / 2, cz = D / 2, r = 17
  cam_set_pos([cx + sin(ang) * cos(lift) * r, 1 + sin(lift) * r, cz + cos(ang) * cos(lift) * r])
  cam_set_lookat([cx, 1.5, cz])
  outline(0)
  map(0)
  outline()
  if (target) {
    let [t, x, y, z, nx, ny, nz] = target
    if (digging) box(x, y, z, 8)
    else box(x + nx, y + ny, z + nz, 7)
  }

  // hotbar: one square per block, the selected one framed in white
  rectfill(28, 228, 32 + BLOCKS.length * 22, 253, 0)
  for (let i = 0; i < BLOCKS.length; i++) {
    let x = 32 + i * 22
    rectfill(x + 2, 232, x + 19, 249, ICON[BLOCKS[i]])
    if (i == sel) rect(x, 230, x + 21, 251, 7)
  }
  print(digging ? 'DIG' : 'BUILD', 4, 4, digging ? 8 : 11, 0)
  let hint = 'X: ' + (digging ? 'build' : 'dig') + '  hold X: clear'
  print(hint, 252 - hint.length * 7, 4, 6, 0)
}
